using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Mono.Cecil;
using Mono.Cecil.Cil;
class PatchTool {
 static IEnumerable<TypeDefinition> Types(IEnumerable<TypeDefinition> ts){foreach(var t in ts){yield return t;foreach(var n in Types(t.NestedTypes))yield return n;}}
 static DefaultAssemblyResolver Resolver(string directory){var r=new DefaultAssemblyResolver();r.AddSearchDirectory(directory);r.AddSearchDirectory(@"C:\Program Files (x86)\Steam\steamapps\common\Sea Power\Sea Power_Data\Managed");r.AddSearchDirectory(@"C:\Program Files (x86)\Steam\steamapps\common\Sea Power\BepInEx\core");return r;}
 static ModuleDefinition Read(string p){return ModuleDefinition.ReadModule(p,new ReaderParameters{AssemblyResolver=Resolver(Path.GetDirectoryName(p)),ReadWrite=false});}
 public static int Main(string[] args){try{if(args[0]=="prepare"){
  var m=Read(args[1]);foreach(var t in Types(m.Types)){if(t.Name=="<Module>")continue;if(t.IsNested){t.Attributes=(t.Attributes&~TypeAttributes.VisibilityMask)|TypeAttributes.NestedPublic;}else t.IsPublic=true;
   foreach(var f in t.Fields)f.Attributes=(f.Attributes&~FieldAttributes.FieldAccessMask)|FieldAttributes.Public;
   foreach(var x in t.Methods)x.Attributes=(x.Attributes&~MethodAttributes.MemberAccessMask)|MethodAttributes.Public;
  }m.Write(args[2]);Console.WriteLine("Compilation-only public reference written");return 0;
 }if(args[0]=="inspect"){
  var m=Read(args[1]);foreach(var t in Types(m.Types))foreach(var meth in t.Methods.Where(x=>x.HasBody)){
   if(args.Length>2&&meth.FullName.Contains(args[2])){Console.WriteLine(meth.FullName);foreach(var v in meth.Body.Variables)Console.WriteLine("LOCAL "+v.Index+" "+v.VariableType);foreach(var ins in meth.Body.Instructions)Console.WriteLine(ins);}
   if(args.Length==2)foreach(var i in meth.Body.Instructions){var mr=i.Operand as MethodReference;if(mr!=null&&mr.DeclaringType.FullName=="FlightDeckOpsMod.DeckOpsZones"&&new[]{"AssignLaunch","AssignLaunchTo","LaunchFromLaunchPoint"}.Contains(mr.Name))Console.WriteLine(t.FullName+"::"+meth.Name+" -> "+mr.Name);}
  }return 0;
 }return Build(args[1],args[2],args[3]);}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static ModuleDefinition target;static Dictionary<string,TypeDefinition> localTypes;static Dictionary<string,MethodDefinition> helperMethods;static Dictionary<string,FieldDefinition> helperFields;
 static TypeReference MT(TypeReference t){if(t==null)return null;var gp=t as GenericParameter;if(gp!=null)return gp;var gi=t as GenericInstanceType;if(gi!=null){var n=new GenericInstanceType(MT(gi.ElementType));foreach(var a in gi.GenericArguments)n.GenericArguments.Add(MT(a));return n;}var ar=t as ArrayType;if(ar!=null)return new ArrayType(MT(ar.ElementType),ar.Rank);var br=t as ByReferenceType;if(br!=null)return new ByReferenceType(MT(br.ElementType));var ptr=t as PointerType;if(ptr!=null)return new PointerType(MT(ptr.ElementType));TypeDefinition own;if(localTypes.TryGetValue(t.FullName,out own)){if(own.IsNestedPrivate)own.IsNestedAssembly=true;return own;}return target.ImportReference(t);}
 static FieldReference MF(FieldReference f){FieldDefinition h;if(helperFields.TryGetValue(f.FullName,out h))return h;TypeDefinition own;if(localTypes.TryGetValue(f.DeclaringType.FullName,out own)){var field=own.Fields.Single(x=>x.Name==f.Name);if(field.IsPrivate)field.IsAssembly=true;return field;}return new FieldReference(f.Name,MT(f.FieldType),MT(f.DeclaringType));}
 static MethodReference MM(MethodReference m){var gm=m as GenericInstanceMethod;if(gm!=null){var n=new GenericInstanceMethod(MM(gm.ElementMethod));foreach(var a in gm.GenericArguments)n.GenericArguments.Add(MT(a));return n;}MethodDefinition h;if(helperMethods.TryGetValue(m.FullName,out h))return h;TypeDefinition own;if(localTypes.TryGetValue(m.DeclaringType.FullName,out own)){var found=own.Methods.Single(x=>x.FullName==m.FullName);if(found.IsPrivate)found.IsAssembly=true;return found;}var r=new MethodReference(m.Name,MT(m.ReturnType),MT(m.DeclaringType)){HasThis=m.HasThis,ExplicitThis=m.ExplicitThis,CallingConvention=m.CallingConvention};foreach(var p in m.Parameters)r.Parameters.Add(new ParameterDefinition(MT(p.ParameterType)));foreach(var g in m.GenericParameters)r.GenericParameters.Add(new GenericParameter(g.Name,r));return r;}
 static MethodDefinition Method(string type,string name){return localTypes["FlightDeckOpsMod."+type].Methods.Single(m=>m.Name==name);}
 static MethodDefinition Helper(string name){return localTypes["FlightDeckOpsMod.CodexFixes"].Methods.Single(m=>m.Name==name);}
 static void Replace(MethodDefinition m,string helper){m.Body=new MethodBody(m);var il=m.Body.GetILProcessor();foreach(var p in m.Parameters)il.Append(Instruction.Create(OpCodes.Ldarg,p));il.Append(Instruction.Create(OpCodes.Call,Helper(helper)));il.Append(Instruction.Create(OpCodes.Ret));}
 static void InsertBefore(MethodDefinition m,Instruction at,params Instruction[] instructions){var il=m.Body.GetILProcessor();foreach(var i in instructions)il.InsertBefore(at,i);}
 static void LongBranches(MethodDefinition m){var map=new Dictionary<Code,OpCode>{{Code.Br_S,OpCodes.Br},{Code.Brfalse_S,OpCodes.Brfalse},{Code.Brtrue_S,OpCodes.Brtrue},{Code.Beq_S,OpCodes.Beq},{Code.Bge_S,OpCodes.Bge},{Code.Bge_Un_S,OpCodes.Bge_Un},{Code.Bgt_S,OpCodes.Bgt},{Code.Bgt_Un_S,OpCodes.Bgt_Un},{Code.Ble_S,OpCodes.Ble},{Code.Ble_Un_S,OpCodes.Ble_Un},{Code.Blt_S,OpCodes.Blt},{Code.Blt_Un_S,OpCodes.Blt_Un},{Code.Bne_Un_S,OpCodes.Bne_Un},{Code.Leave_S,OpCodes.Leave}};foreach(var i in m.Body.Instructions){OpCode op;if(map.TryGetValue(i.OpCode.Code,out op))i.OpCode=op;}}
 static int Build(string original,string helper,string output){
  target=Read(original);var source=Read(helper);localTypes=Types(target.Types).ToDictionary(t=>t.FullName);helperMethods=new Dictionary<string,MethodDefinition>();helperFields=new Dictionary<string,FieldDefinition>();
  var st=source.Types.Single(t=>t.Name=="CodexFixes");var nt=new TypeDefinition(st.Namespace,st.Name,st.Attributes,target.ImportReference(typeof(object)));target.Types.Add(nt);localTypes[nt.FullName]=nt;
  foreach(var f in st.Fields){var n=new FieldDefinition(f.Name,f.Attributes,MT(f.FieldType));if(f.HasConstant)n.Constant=f.Constant;nt.Fields.Add(n);helperFields[f.FullName]=n;}
  foreach(var m in st.Methods){var n=new MethodDefinition(m.Name,m.Attributes,MT(m.ReturnType));n.ImplAttributes=m.ImplAttributes;foreach(var p in m.Parameters)n.Parameters.Add(new ParameterDefinition(p.Name,p.Attributes,MT(p.ParameterType)));nt.Methods.Add(n);helperMethods[m.FullName]=n;}
  foreach(var m in st.Methods){if(!m.HasBody)continue;var n=helperMethods[m.FullName];n.Body=new MethodBody(n){InitLocals=m.Body.InitLocals,MaxStackSize=m.Body.MaxStackSize};foreach(var v in m.Body.Variables)n.Body.Variables.Add(new VariableDefinition(MT(v.VariableType)));var ins=new Dictionary<Instruction,Instruction>();foreach(var i in m.Body.Instructions){var c=Instruction.Create(OpCodes.Nop);c.OpCode=i.OpCode;n.Body.Instructions.Add(c);ins[i]=c;}
   foreach(var i in m.Body.Instructions){object o=i.Operand;if(o is Instruction)o=ins[(Instruction)o];else if(o is Instruction[])o=((Instruction[])o).Select(x=>ins[x]).ToArray();else if(o is VariableDefinition)o=n.Body.Variables[((VariableDefinition)o).Index];else if(o is ParameterDefinition)o=n.Parameters[((ParameterDefinition)o).Index];else if(o is MethodReference)o=MM((MethodReference)o);else if(o is FieldReference)o=MF((FieldReference)o);else if(o is TypeReference)o=MT((TypeReference)o);else if(o is CallSite)throw new Exception("Unsupported callsite");ins[i].Operand=o;}
   foreach(var eh in m.Body.ExceptionHandlers)n.Body.ExceptionHandlers.Add(new ExceptionHandler(eh.HandlerType){TryStart=eh.TryStart==null?null:ins[eh.TryStart],TryEnd=eh.TryEnd==null?null:ins[eh.TryEnd],HandlerStart=eh.HandlerStart==null?null:ins[eh.HandlerStart],HandlerEnd=eh.HandlerEnd==null?null:ins[eh.HandlerEnd],FilterStart=eh.FilterStart==null?null:ins[eh.FilterStart],CatchType=MT(eh.CatchType)});
  }
  Replace(Method("DeckOpsTaxiGraph","FindRoute"),"FindRoute");Replace(Method("DeckOpsMove","BuildRoute"),"BuildRoute");Replace(Method("DeckOpsAirOpsBridge","Tick"),"AutoTick");
  int listOps=0,manualCalls=0,dispatch=0;var ops=new Dictionary<string,string>{{"Add","VectorAdd"},{"AddRange","VectorAddRange"},{"Clear","VectorClear"},{"RemoveAt","VectorRemoveAt"},{"Insert","VectorInsert"},{"set_Item","VectorSet"}};
  foreach(var t in Types(target.Types).Where(x=>x!=nt))foreach(var m in t.Methods.Where(x=>x.HasBody))foreach(var i in m.Body.Instructions.ToArray()){
   var mr=i.Operand as MethodReference;if(mr==null)continue;var gt=mr.DeclaringType as GenericInstanceType;string name;
   if(gt!=null&&gt.ElementType.FullName=="System.Collections.Generic.List`1"&&gt.GenericArguments.Count==1&&gt.GenericArguments[0].FullName=="UnityEngine.Vector3"&&ops.TryGetValue(mr.Name,out name)){i.OpCode=OpCodes.Call;i.Operand=Helper(name);listOps++;}
   if(mr.DeclaringType.FullName=="FlightDeckOpsMod.DeckOpsZones"&&new[]{"AssignLaunch","AssignLaunchTo","LaunchFromLaunchPoint"}.Contains(mr.Name)&&(t.FullName.Contains("DeckOpsDeckPanel")||t.FullName.Contains("DeckOpsPanelRoot")||t.FullName.Contains("DeckOpsVanillaContextMenu")||t.FullName.Contains("FlightDeckOpsUi"))){i.Operand=Helper("Manual"+mr.Name);i.OpCode=OpCodes.Call;manualCalls++;}
   if(mr.DeclaringType.FullName=="FlightDeckOpsMod.DeckOpsMove"&&mr.Name=="NodeAtPushOut"){i.Operand=Helper("DispatchAtPushOut");dispatch++;}
  }
  if(listOps<25||manualCalls!=10||dispatch<1)throw new Exception("Unexpected hook counts: "+listOps+" / "+manualCalls+" / "+dispatch);
  var advance=Method("DeckOpsMove","Advance");int drive=0,tolerance=0;
  foreach(var i in advance.Body.Instructions.ToArray()){var mr=i.Operand as MethodReference;if(mr!=null&&mr.Name=="set_CommandPosition"){InsertBefore(advance,i,Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Call,Helper("ApplyRouteDrive")));drive++;}if(i.OpCode.Code==Code.Ldc_R4&&Math.Abs((float)i.Operand-.07440469f)<.00000001f){i.OpCode=OpCodes.Ldarg_1;i.Operand=null;advance.Body.GetILProcessor().InsertAfter(i,Instruction.Create(OpCodes.Call,Helper("CornerTolerance")));tolerance++;}}
  if(drive!=2||tolerance!=1)throw new Exception("Advance hooks mismatch");
  var arrive=Method("DeckOpsMove","Arrive");InsertBefore(arrive,arrive.Body.Instructions[0],Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Ldarg_1),Instruction.Create(OpCodes.Call,Helper("ResetRouteDrive")));
  var cancel=Method("DeckOpsZones","CancelLaunchWait");foreach(var i in cancel.Body.Instructions.Where(x=>x.OpCode.Code==Code.Ret).ToArray())InsertBefore(cancel,i,Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Call,Helper("AfterCancel")));
  foreach(var name in new[]{"AssignLaunch","AssignLaunchTo","LaunchFromLaunchPoint"}){var m=Method("DeckOpsZones",name);var first=m.Body.Instructions[0];InsertBefore(m,first,Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Call,Helper("PermitLaunch")),Instruction.Create(OpCodes.Brtrue,first),Instruction.Create(OpCodes.Ldc_I4_0),Instruction.Create(OpCodes.Ret));}
  var spawn=Method("DeckOpsLaunchScheduler","Spawn");var call=spawn.Body.Instructions.Single(i=>i.Operand is MethodReference&&((MethodReference)i.Operand).Name=="launchVehicle");var order=localTypes["FlightDeckOpsMod.DeckOpsLaunchScheduler/Order"];InsertBefore(spawn,call.Next,Instruction.Create(OpCodes.Dup),Instruction.Create(OpCodes.Ldarg_0),Instruction.Create(OpCodes.Ldfld,order.Fields.Single(f=>f.Name=="Ltp")),Instruction.Create(OpCodes.Call,Helper("MarkSpawned")));
  foreach(var t in Types(target.Types))foreach(var m in t.Methods.Where(x=>x.HasBody))LongBranches(m);
  if(target.AssemblyReferences.Any(a=>a.Name=="FixHelper"||a.Name=="FlightDeckOpsMod"))throw new Exception("Unexpected helper/self dependency");
  target.Write(output);Console.WriteLine("PATCHED: list operations="+listOps+", manual launch hooks="+manualCalls+", dispatch hooks="+dispatch+", direction hooks="+drive);return 0;
 }
}